class Solution {
public:
    vector<string> removeComments(vector<string>& source) {
        vector<string> res;
        bool inBlock = false;
        string cur;
        for (auto& line : source) {
            int i = 0, n = (int)line.size();
            while (i < n) {
                if (!inBlock) {
                    if (i + 1 < n && line[i] == '/' && line[i+1] == '/') {
                        break;
                    } else if (i + 1 < n && line[i] == '/' && line[i+1] == '*') {
                        inBlock = true;
                        i += 2;
                    } else {
                        cur += line[i];
                        i += 1;
                    }
                } else {
                    if (i + 1 < n && line[i] == '*' && line[i+1] == '/') {
                        inBlock = false;
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
            }
            if (!inBlock) {
                if (!cur.empty()) {
                    res.push_back(cur);
                    cur.clear();
                }
            }
        }
        return res;
    }
};
